import{V as ee,et as te,mt as e,tt as ne}from"./chunks/framework.Bb5YUzRP.js";import{$ as t,$t as n,A as re,At as r,B as i,Bt as a,Ct as o,D as s,Dt as c,E as l,Et as u,F as d,Ft as f,G as p,Gt as m,H as h,Ht as g,I as _,It as v,J as y,Jt as b,K as x,Kt as S,L as C,Lt as w,M as T,Mt as E,N as D,Nt as O,O as k,Ot as A,P as j,Pt as M,Q as N,Qt as P,R as F,Rt as I,St as L,T as R,Tt as z,U as B,Ut as V,V as H,Vt as U,W,Wt as G,X as K,Xt as q,Y as J,Yt as Y,Z as X,Zt as Z,_t as ie,at as ae,bt as oe,ct as se,dt as ce,en as Q,et as le,ft as ue,gt as de,ht as fe,it as pe,j as me,jt as he,k as ge,kt as _e,lt as ve,mt as ye,nt as be,ot as xe,pt as Se,q as $,qt as Ce,rt as we,st as Te,tt as Ee,ut as De,vt as Oe,wt as ke,xt as Ae,yt as je,z as Me,zt as Ne}from"./chunks/assets.7fkIx-_A.js";var Pe=JSON.parse(`{"title":"Visual options","description":"","frontmatter":{},"headers":[],"relativePath":"product-config/visual-options.md","filePath":"product-config/visual-options.md"}`),Fe={name:`product-config/visual-options.md`},Ie=Q+` 1x, `+n+` 2x`,Le=P+` 1x, `+Z+` 2x`,Re=q+` 1x, `+Y+` 2x`,ze=b+` 1x, `+Ce+` 2x`,Be=S+` 1x, `+m+` 2x`,Ve=G+` 1x, `+V+` 2x`,He=g+` 1x, `+U+` 2x`,Ue=a+` 1x, `+Ne+` 2x`,We=I+` 1x, `+w+` 2x`,Ge=v+` 1x, `+f+` 2x`,Ke=M+` 1x, `+O+` 2x`,qe=E+` 1x, `+he+` 2x`,Je=r+` 1x, `+_e+` 2x`,Ye=A+` 1x, `+c+` 2x`,Xe=u+` 1x, `+z+` 2x`,Ze=ke+` 1x, `+o+` 2x`,Qe=L+` 1x, `+Ae+` 2x`,$e=Q+` 1x, `+n+` 2x`,et=P+` 1x, `+Z+` 2x`,tt=oe+` 1x, `+je+` 2x`,nt=Oe+` 1x, `+ie+` 2x`,rt=de+` 1x, `+fe+` 2x`,it=ye+` 1x, `+Se+` 2x`,at=ue+` 1x, `+ce+` 2x`,ot=De+` 1x, `+ve+` 2x`,st=se+` 1x, `+Te+` 2x`,ct=xe+` 1x, `+ae+` 2x`,lt=pe+` 1x, `+we+` 2x`,ut=be+` 1x, `+Ee+` 2x`,dt=le+` 1x, `+t+` 2x`,ft=N+` 1x, `+X+` 2x`,pt=K+` 1x, `+J+` 2x`,mt=y+` 1x, `+$+` 2x`,ht=x+` 1x, `+p+` 2x`,gt=W+` 1x, `+B+` 2x`,_t=h+` 1x, `+H+` 2x`,vt=i+` 1x, `+Me+` 2x`,yt=F+` 1x, `+C+` 2x`,bt=_+` 1x, `+d+` 2x`,xt=j+` 1x, `+D+` 2x`,St=T+` 1x, `+me+` 2x`,Ct=re+` 1x, `+ge+` 2x`,wt=k+` 1x, `+s+` 2x`,Tt=l+` 1x, `+R+` 2x`;function Et(ee,t,n,re,r,i){return e(),te(`div`,null,[...t[0]||=[ne(`<h1 id="visual-options" tabindex="-1">Visual options <a class="header-anchor" href="#visual-options" aria-label="Permalink to “Visual options”">​</a></h1><p>The module can display a visual configurator where the customer can pick different parts of the product and get a direct preview of the selected options.</p><p><img src="/webp/visual-options-visual-options-display.jpg-90-1791641242066.webp" srcset="`+Ie+`" alt="Visual options display" title="" width="2240" height="1684" loading="lazy" style="width:1120px;"></p><p><img src="/webp/visual-options-visual-options-display-2.jpg-90-1791641242064.webp" srcset="`+Le+`" alt="Visual options display 2" title="" width="2244" height="1688" loading="lazy" style="width:1122px;"></p><p>In this example, we will configure a custom skateboard step by step to see how to add option groups and visual options to the designer.</p><h2 id="enabling-the-visual-options" tabindex="-1">1️⃣ Enabling the visual options <a class="header-anchor" href="#enabling-the-visual-options" aria-label="Permalink to “Enabling the visual options”">​</a></h2><p>The first step is to enable the visual options</p><p><img src="/webp/visual-options-enable.jpg-90-1791641242054.webp" srcset="`+Re+`" alt="Visual options enable" title="" width="1572" height="1032" loading="lazy" style="width:786px;"></p><h2 id="background-image" tabindex="-1">2️⃣ Background image <a class="header-anchor" href="#background-image" aria-label="Permalink to “Background image”">​</a></h2><p>Then we will open the <a href="/product-config/images.html">images tab</a> and configure a white background to replace the base image</p><p><img src="/webp/visual-bg.jpg-90-1791641242049.webp" srcset="`+ze+`" alt="Visual bg" title="" width="1390" height="438" loading="lazy" style="width:695px;"></p><h2 id="option-groups" tabindex="-1">3️⃣ Option groups <a class="header-anchor" href="#option-groups" aria-label="Permalink to “Option groups”">​</a></h2><p>We can then add our option groups</p><ul><li>Click this button</li></ul><p><img src="/webp/visual-add-group.jpg-90-1791641242049.webp" srcset="`+Be+`" alt="Visual add group" title="" width="666" height="258" loading="lazy" style="width:333px;"></p><p>A new empty group will be created</p><ul><li>Click the group title to edit it</li></ul><p><img src="/webp/new-group.jpg-90-1791641241997.webp" srcset="`+Ve+`" alt="New group" title="" width="598" height="582" loading="lazy" style="width:299px;"></p><p>This modal will be displayed</p><p><img src="/webp/group-visual-edit.jpg-90-1791641241945.webp" srcset="`+He+`" alt="Group visual edit" title="" width="555" height="962" loading="lazy" style="width:277.5px;"></p><p>Change the title to &quot;Board&quot;. Our skateboard will have three groups called: Board, Artwork and Wheels.</p><p>You can create the other two groups in the same way.</p><p><img src="/webp/visual-groups.jpg-90-1791641242050.webp" srcset="`+Ue+`" alt="Visual groups" title="" width="590" height="1210" loading="lazy" style="width:295px;"></p><h2 id="options" tabindex="-1">4️⃣ Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><p>Next up, we add different options to each group</p><p>We can add options individually by clicking this button</p><p><img src="/webp/layer-btn.jpg-90-1791641241989.webp" srcset="`+We+`" alt="Layer btn" title="" width="592" height="396" loading="lazy" style="width:296px;"></p><p>Then, an empty option will be created. We can click on the empty image and empty icon to import a file.</p><p>The supported file types are: <code>svg</code>, <code>png</code>, <code>jpg</code>, <code>jpeg</code></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Leave the icon image empty if you want to use a color instead</p></div><p>The option image should have a transparent background to allow the graphical superposition of the various visual options.</p><p>Here are some examples:</p><p><img src="/webp/visual-options-retro.png-90-1791641242062.webp" srcset="`+Ge+`" alt="Retro" title="" width="952" height="952" loading="lazy" style="width:476px;"></p><p><img src="/webp/visual-options-mountains.png-90-1791641242059.webp" srcset="`+Ke+`" alt="Mountains" title="" width="952" height="952" loading="lazy" style="width:476px;"></p><p><img src="/webp/visual-options-blue.png-90-1791641242052.webp" srcset="`+qe+`" alt="Blue" title="" width="952" height="952" loading="lazy" style="width:476px;"></p><p>When we combine the three images above, we get this result</p><p><img src="/webp/visual-options-result.png-90-1791641242061.webp" srcset="`+Je+`" alt="Result" title="" width="956" height="967" loading="lazy" style="width:478px;"></p><div class="tip custom-block"><p class="custom-block-title">Importing multiple options</p><p>You can import all options at once by clicking the import button then selecting multiple files.<br><img src="/webp/visual-options-import-btn.jpg-90-1791641242055.webp" srcset="`+Ye+`" alt="Import btn" title="" width="128" height="72" loading="lazy" style="width:64px;"></p><p>The module will create the necessary options and generate the icons and the names automatically.</p><p>Make sure to name your files correctly, because the module will use the file names as the option names when importing multiple files.</p></div><p>After importing the layers, they should look like this</p><p><img src="/webp/visual-options-options.jpg-90-1791641242060.webp" srcset="`+Xe+`" alt="Options" title="" width="598" height="802" loading="lazy" style="width:299px;"></p><p>We can edit an option y clicking on its title. This modal will be displayed.</p><p><img src="/webp/visual-options-option-modal.jpg-90-1791641242059.webp" srcset="`+Ze+`" alt="Option modal" title="" width="558" height="1032" loading="lazy" style="width:279px;"></p><p>We can change the option label and price as well as its status and its description.</p><p>We add the options to other groups in the same way.</p><h2 id="initial-options" tabindex="-1">5️⃣ Initial options <a class="header-anchor" href="#initial-options" aria-label="Permalink to “Initial options”">​</a></h2><p>We can pick initial options by clicking this button on the desired options</p><p><img src="/webp/visual-options-initial-options.jpg-90-1791641242058.webp" srcset="`+Qe+`" alt="Initial options" title="" width="1974" height="1724" loading="lazy" style="width:987px;"></p><h2 id="visual-options-interface" tabindex="-1">6️⃣ Visual options interface <a class="header-anchor" href="#visual-options-interface" aria-label="Permalink to “Visual options interface”">​</a></h2><p>In the designer, the visual options will be displayed like this</p><p><img src="/webp/visual-options-visual-options-display.jpg-90-1791641242066.webp" srcset="`+$e+`" alt="Visual options display" title="" width="2240" height="1684" loading="lazy" style="width:1120px;"></p><p>The customer can pick and option from each group to form the desired product.</p><p><img src="/webp/visual-options-visual-options-display-2.jpg-90-1791641242064.webp" srcset="`+et+`" alt="Visual options display 2" title="" width="2244" height="1688" loading="lazy" style="width:1122px;"></p><p>Here&#39;s how the price is displayed when the option has a price</p><p><img src="/webp/visual-options-option-price.jpg-90-1791641242059.webp" srcset="`+tt+`" alt="Option price" title="" width="630" height="558" loading="lazy" style="width:315px;"></p><h2 id="option-colorization" tabindex="-1">🎨 Option colorization <a class="header-anchor" href="#option-colorization" aria-label="Permalink to “Option colorization”">​</a></h2><p>You can generate options by colorizing an image using multiple colors.</p><p>In this example, we will colorize this image</p><p><img src="/webp/visual-options-dial.png-90-1791641242053.webp" srcset="`+nt+`" alt="Dial" title="" width="800" height="800" loading="lazy" style="width:400px;"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>For an effective colorization, you need to provide the white version of the option</p></div><p>We start by creating an option and adding the image</p><p><img src="/webp/visual-options-colorize-btn.jpg-90-1791641242052.webp" srcset="`+rt+`" alt="Colorize btn" title="" width="598" height="396" loading="lazy" style="width:299px;"></p><p>We then click the desired colors and generate the layers</p><p><img src="/webp/visual-options-colors.jpg-90-1791641242052.webp" srcset="`+it+`" alt="Colors" title="" width="936" height="418" loading="lazy" style="width:468px;"></p><p>The module will generate the options like this</p><p><img src="/webp/visual-options-generated.jpg-90-1791641242055.webp" srcset="`+at+`" alt="Generated" title="" width="596" height="1366" loading="lazy" style="width:298px;"></p><p>You can delete the icons if you want to display the colors</p><p>Here&#39;s how the generated options will look</p><p><img src="/webp/visual-options-dials.jpg-90-1791641242053.webp" srcset="`+ot+`" alt="Dials" title="" width="1032" height="862" loading="lazy" style="width:516px;"></p><p>You can also use textures to colorize the option. Make sure that your texture is seamless so that it could be tiled properly over the option image.</p><p>Here&#39;s an option that was colorized using an aluminium texture</p><p><img src="/webp/visual-options-alu.jpg-90-1791641242051.webp" srcset="`+st+`" alt="Alu" title="" width="1102" height="1084" loading="lazy" style="width:551px;"></p><h2 id="sync-with-dynamic-product" tabindex="-1">🔄 Sync with Dynamic Product <a class="header-anchor" href="#sync-with-dynamic-product" aria-label="Permalink to “Sync with Dynamic Product”">​</a></h2><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>This option is only available if you have installed the <a href="https://dynamic-docs.prestalife.net/" target="_blank" rel="noreferrer">Dynamic Product</a> module</p></div><p>If you want to display visual options in Dynamic Product by displaying <a href="https://dynamic-docs.prestalife.net/fields#image-list" target="_blank" rel="noreferrer">image lists</a>, you can enable the <code>Sync with Dynamic Product</code> option.</p><p>The module will tell you what to name the <a href="https://dynamic-docs.prestalife.net/fields" target="_blank" rel="noreferrer">Dynamic Product field</a></p><p><img src="/webp/sync-option.jpg-90-1791641242031.webp" srcset="`+ct+`" alt="Sync option" title="" width="533" height="1082" loading="lazy" style="width:266.5px;"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>For the sync to work, the options must use the same images and in the same order</p></div><p>Example:</p><p>Board options group in Product Designer</p><p><img src="/webp/board-options-designer.jpg-90-1791641241917.webp" srcset="`+lt+`" alt="Board options designer" title="" width="594" height="1366" loading="lazy" style="width:297px;"></p><p>Board image list field in Dynamic Product</p><p><img src="/webp/border-image-list.jpg-90-1791641241918.webp" srcset="`+ut+`" alt="Border image list" title="" width="1598" height="530" loading="lazy" style="width:799px;"></p><p>The image lists and the designer will be displayed like this</p><p><img src="/webp/sync-result.jpg-90-1791641242033.webp" srcset="`+dt+`" alt="Sync result" title="" width="1900" height="1918" loading="lazy" style="width:950px;"></p><p>Notice that the Options tab in the designer was hidden to avoid displaying the options twice.</p><h2 id="using-sub-groups" tabindex="-1">*️⃣ Using sub-groups <a class="header-anchor" href="#using-sub-groups" aria-label="Permalink to “Using sub-groups”">​</a></h2><p>You can add sub-groups to any option group by clicking the subgroup button</p><p><img src="/webp/add-subgroup.jpg-90-1791641241899.webp" srcset="`+ft+`" alt="Add subgroup" title="" width="794" height="446" loading="lazy" style="width:397px;"></p><p>A new sub-group will be added inside the option group</p><p><img src="/webp/new-subgroup.jpg-90-1791641241997.webp" srcset="`+pt+`" alt="New subgroup" title="" width="796" height="1024" loading="lazy" style="width:398px;"></p><p>You can add the options and import them as normal, the sub-group is identical to a normal group.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>It&#39;s preferred that the parent group does not contain any options but only sub-groups</p></div><p>The sub-groups will be displayed like this</p><p><img src="/webp/subgroups-display.jpg-90-1791641242028.webp" srcset="`+mt+`" alt="Subgroups display" title="" width="638" height="780" loading="lazy" style="width:319px;"></p><p>In this case the <code>Board</code> group contains two sub-groups which are <code>Color</code> and <code>Artwork</code></p><h3 id="single-choice" tabindex="-1">Single choice <a class="header-anchor" href="#single-choice" aria-label="Permalink to “Single choice”">​</a></h3><p>You can enable the single choice setting on the parent group to allow only one option inside the group and its sub-groups to be selected.</p><p><img src="/webp/single-choice.png-90-1791641242022.webp" srcset="`+ht+`" alt="Single choice" title="" width="712" height="1154" loading="lazy" style="width:356px;"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Setting a sub-group that belongs to a single choice group as required will have no effect on the validation.</p></div><h2 id="design-layer" tabindex="-1">🖼️ Design layer <a class="header-anchor" href="#design-layer" aria-label="Permalink to “Design layer”">​</a></h2><p>By default, the design items will be inserted on top of the visual options layers.</p><p>To have more control on the order, you can insert a design layer between the option groups.</p><p><img src="/webp/design-layer-btn.jpg-90-1791641241929.webp" srcset="`+gt+`" alt="Design layer btn" title="" width="462" height="72" loading="lazy" style="width:231px;"></p><p>In this example, we want to display the image item under the frame which comes as a visual option.</p><p><img src="/webp/frames.jpg-90-1791641241945.webp" srcset="`+_t+`" alt="Frames" title="" width="640" height="576" loading="lazy" style="width:320px;"></p><p>To insert the image under the frame, we can add a design layer and move it to the top of list.</p><p><img src="/webp/frames-layers.jpg-90-1791641241944.webp" srcset="`+vt+`" alt="Frames layers" title="" width="794" height="1482" loading="lazy" style="width:397px;"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The visual order on the product page will be reversed. So the top layer will be displayed on the bottom and so on.</p></div><p>The result will look like this depending on the selected frame</p><p><img src="/webp/frame-flowers.jpg-90-1791641241942.webp" srcset="`+yt+`" alt="Frame flowers" title="" width="2200" height="1642" loading="lazy" style="width:1100px;"></p><p><img src="/webp/layers-random.jpg-90-1791641241992.webp" srcset="`+bt+`" alt="Layers random" title="" width="2194" height="1642" loading="lazy" style="width:1097px;"></p><p><img src="/webp/frames-circle.jpg-90-1791641241944.webp" srcset="`+xt+`" alt="Frames circle" title="" width="2198" height="1642" loading="lazy" style="width:1099px;"></p><h2 id="importing-layers" tabindex="-1">⬇️ Importing layers <a class="header-anchor" href="#importing-layers" aria-label="Permalink to “Importing layers”">​</a></h2><p>You can import layers by uploading multiple images at once.</p><p><img src="/webp/visual-options-import-files.jpg-90-1791641242056.webp" srcset="`+St+`" alt="Import files" title="" width="858" height="456" loading="lazy" style="width:429px;"></p><p>You can also import icons by naming the files like this</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>file1.png</span></span>
<span class="line"><span>file1-icon.png</span></span>
<span class="line"><span></span></span>
<span class="line"><span>file2.png</span></span>
<span class="line"><span>file2-icon.png</span></span>
<span class="line"><span></span></span>
<span class="line"><span>file3.png</span></span>
<span class="line"><span>file3-icon.png</span></span></code></pre></div><p>The module will automatically detect the icon files and import them and assign them to the corresponding image.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The icon extension does not have to be the same as the image extension.</p></div><h2 id="🪄-dynamic-colors" tabindex="-1">🪄 Dynamic colors <a class="header-anchor" href="#🪄-dynamic-colors" aria-label="Permalink to “🪄 Dynamic colors”">​</a></h2><p>If you want to allow the customer to change the color of an option freely, you can enable the <code>Dynamic colors</code> option in any layer settings.</p><p><img src="/webp/layer-dynamic-color.png-90-1791641241990.webp" srcset="`+Ct+`" alt="Layer dynamic color" title="" width="906" height="1480" loading="lazy" style="width:453px;"></p><p>The icon color will be used as the initial color of the layer.</p><p><img src="/webp/admin-layers-preview.png-90-1791641241900.webp" srcset="`+wt+`" alt="Admin layers preview" title="" width="1848" height="1268" loading="lazy" style="width:924px;"></p><p>The customer can change the layer color by choosing from the color picker.</p><p><img src="/webp/layer-color-picker.png-90-1791641241989.webp" srcset="`+Tt+`" alt="Layer color picker" title="" width="1604" height="992" loading="lazy" style="width:802px;"></p><p>Make sure to use the white version of the layer to allow the colorization to be effective.</p>`,127)]])}var Dt=ee(Fe,[[`render`,Et]]);export{Pe as __pageData,Dt as default};